create table if not exists public.marketing_visitors(visitor_id uuid primary key,first_seen_at timestamptz not null default now(),last_seen_at timestamptz not null default now(),visit_count bigint not null default 0,first_landing_path text,last_landing_path text,first_referrer text,last_referrer text,utm_source text,utm_medium text,utm_campaign text,utm_content text,utm_term text,gclid text,gbraid text,wbraid text,ip_hash text,country text,region text,city text,user_agent text,browser text,operating_system text,device_type text,analytics_consent text not null default 'granted' check(analytics_consent in ('granted','denied')),converted_user_id uuid references auth.users(id) on delete set null,converted_at timestamptz,updated_at timestamptz not null default now());
create table if not exists public.marketing_page_events(id bigint generated always as identity primary key,visitor_id uuid not null references public.marketing_visitors(visitor_id) on delete cascade,session_id uuid not null,event_type text not null check(event_type in ('page_view','click','signup_completed')),path text not null,label text,element_type text,utm_content text,occurred_at timestamptz not null default now(),metadata jsonb not null default '{}'::jsonb);
alter table public.marketing_visitors enable row level security;alter table public.marketing_page_events enable row level security;
create index if not exists marketing_page_events_visitor_idx on public.marketing_page_events(visitor_id,occurred_at desc);create index if not exists marketing_page_events_path_idx on public.marketing_page_events(path,occurred_at desc);create index if not exists marketing_visitors_content_idx on public.marketing_visitors(utm_content,last_seen_at desc);
create or replace function public.record_marketing_visitor_event(p_visitor_id uuid,p_session_id uuid,p_event_type text,p_path text,p_label text,p_element_type text,p_referrer text,p_utm_source text,p_utm_medium text,p_utm_campaign text,p_utm_content text,p_utm_term text,p_gclid text,p_gbraid text,p_wbraid text,p_ip_hash text,p_country text,p_region text,p_city text,p_user_agent text,p_browser text,p_operating_system text,p_device_type text,p_metadata jsonb default '{}'::jsonb) returns void language plpgsql security definer set search_path=public as $$ begin
if p_event_type not in ('page_view','click') then raise exception 'Invalid analytics event.';end if;
insert into public.marketing_visitors(visitor_id,visit_count,first_landing_path,last_landing_path,first_referrer,last_referrer,utm_source,utm_medium,utm_campaign,utm_content,utm_term,gclid,gbraid,wbraid,ip_hash,country,region,city,user_agent,browser,operating_system,device_type) values(p_visitor_id,case when p_event_type='page_view' then 1 else 0 end,left(p_path,1000),left(p_path,1000),left(p_referrer,2000),left(p_referrer,2000),left(p_utm_source,200),left(p_utm_medium,200),left(p_utm_campaign,200),left(p_utm_content,200),left(p_utm_term,200),left(p_gclid,500),left(p_gbraid,500),left(p_wbraid,500),p_ip_hash,left(p_country,20),left(p_region,100),left(p_city,100),left(p_user_agent,1000),left(p_browser,100),left(p_operating_system,100),left(p_device_type,50)) on conflict(visitor_id) do update set last_seen_at=now(),visit_count=marketing_visitors.visit_count+case when p_event_type='page_view' then 1 else 0 end,last_landing_path=left(p_path,1000),last_referrer=coalesce(nullif(left(p_referrer,2000),''),marketing_visitors.last_referrer),utm_source=coalesce(nullif(left(p_utm_source,200),''),marketing_visitors.utm_source),utm_medium=coalesce(nullif(left(p_utm_medium,200),''),marketing_visitors.utm_medium),utm_campaign=coalesce(nullif(left(p_utm_campaign,200),''),marketing_visitors.utm_campaign),utm_content=coalesce(nullif(left(p_utm_content,200),''),marketing_visitors.utm_content),utm_term=coalesce(nullif(left(p_utm_term,200),''),marketing_visitors.utm_term),gclid=coalesce(nullif(left(p_gclid,500),''),marketing_visitors.gclid),gbraid=coalesce(nullif(left(p_gbraid,500),''),marketing_visitors.gbraid),wbraid=coalesce(nullif(left(p_wbraid,500),''),marketing_visitors.wbraid),ip_hash=coalesce(p_ip_hash,marketing_visitors.ip_hash),country=coalesce(p_country,marketing_visitors.country),region=coalesce(p_region,marketing_visitors.region),city=coalesce(p_city,marketing_visitors.city),user_agent=coalesce(p_user_agent,marketing_visitors.user_agent),browser=coalesce(p_browser,marketing_visitors.browser),operating_system=coalesce(p_operating_system,marketing_visitors.operating_system),device_type=coalesce(p_device_type,marketing_visitors.device_type),updated_at=now();
insert into public.marketing_page_events(visitor_id,session_id,event_type,path,label,element_type,utm_content,metadata) values(p_visitor_id,p_session_id,p_event_type,left(p_path,1000),left(p_label,500),left(p_element_type,100),left(p_utm_content,200),coalesce(p_metadata,'{}'::jsonb));end;$$;
revoke all on function public.record_marketing_visitor_event(uuid,uuid,text,text,text,text,text,text,text,text,text,text,text,text,text,text,text,text,text,text,text,text,text,jsonb) from public;grant execute on function public.record_marketing_visitor_event(uuid,uuid,text,text,text,text,text,text,text,text,text,text,text,text,text,text,text,text,text,text,text,text,text,jsonb) to service_role;
